import{_ as a,c as t,o as e,ah as o}from"./chunks/framework.5ZZXabC7.js";const c=JSON.parse('{"title":"프로젝트","description":"","frontmatter":{},"headers":[],"relativePath":"projects/index.md","filePath":"projects/index.md","lastUpdated":1756890187000}'),i={name:"projects/index.md"};function s(n,r,l,h,p,d){return e(),t("div",null,[...r[0]||(r[0]=[o('<h1 id="프로젝트" tabindex="-1">프로젝트 <a class="header-anchor" href="#프로젝트" aria-label="Permalink to “프로젝트”">​</a></h1><blockquote><p>&quot;아이디어가 떠오르면 일단 만들어보자!&quot;</p></blockquote><p>실제로 만들어본 것들을 정리해놓은 곳이에요.<br> 왜 만들게 됐는지, 어떤 문제들이 있었는지, 어떻게 해결했는지... 그런 이야기들을 솔직하게 적어놓았어요.</p><h2 id="내가-프로젝트하는-방식" tabindex="-1">내가 프로젝트하는 방식 <a class="header-anchor" href="#내가-프로젝트하는-방식" aria-label="Permalink to “내가 프로젝트하는 방식”">​</a></h2><p><strong>완벽하지 않아도 일단 만들어보기</strong></p><ul><li>기능 다 만들지 못해도 일단 배포는 해보기</li><li>안 되는 부분이 있어도 솔직하게 기록해놓기</li><li>&quot;나중에 고치자&quot; 하면서 일단 완성부터 하기</li></ul><hr><h2 id="완성한-프로젝트" tabindex="-1">완성한 프로젝트 <a class="header-anchor" href="#완성한-프로젝트" aria-label="Permalink to “완성한 프로젝트”">​</a></h2><h3 id="할-일-관리-앱" tabindex="-1"><a href="./todo-app.html">할 일 관리 앱</a> <a class="header-anchor" href="#할-일-관리-앱" aria-label="Permalink to “할 일 관리 앱”">​</a></h3><p><strong>&quot;내가 쓸 용도로 만든 심플한 할 일 앱&quot;</strong></p><p>다른 할일 앱들이 너무 복잡해서 짜증났어요. 그래서 내가 쓸 용도로 정말 간단한 걸 만들어봤어요. React Hooks랑 TypeScript도 제대로 써보고 싶어서 첫 개인 프로젝트로 선택했죠.</p><ul><li><strong>핵심 기술</strong>: React, TypeScript, Tailwind CSS</li><li><strong>주요 배움</strong>: 상태 관리, 로컬 스토리지 활용, 컴포넌트 설계</li><li><strong>개발 기간</strong>: 약 3주 (2024.02~03)</li></ul><p><a href="./todo-app.html">자세히 보기</a> | <a href="https://github.com/jang-oi/todo-app" target="_blank" rel="noreferrer">GitHub</a></p><hr><h3 id="vitepress-포트폴리오-현재-사이트" tabindex="-1">VitePress 포트폴리오 (현재 사이트) <a class="header-anchor" href="#vitepress-포트폴리오-현재-사이트" aria-label="Permalink to “VitePress 포트폴리오 (현재 사이트)”">​</a></h3><p><strong>&quot;마크다운으로 관리하는 개발 블로그&quot;</strong></p><p>단순한 포트폴리오가 아니라 지속적으로 학습 내용을 기록할 수 있는 공간이 필요했습니다. VitePress를 선택한 이유는 마크다운 기반으로 글을 쓰기 편하고, Vue.js도 경험해볼 수 있어서였어요.</p><ul><li><strong>핵심 기술</strong>: VitePress, Vue.js, GitHub Actions</li><li><strong>주요 배움</strong>: 정적 사이트 생성, CI/CD 파이프라인, SEO 최적화</li><li><strong>개발 상태</strong>: 지속적인 개선 중</li></ul><p><a href="https://github.com/jang-oi/portfolio" target="_blank" rel="noreferrer">GitHub</a></p><h2 id="다음에-만들어보고-싶은-것들" tabindex="-1">다음에 만들어보고 싶은 것들 <a class="header-anchor" href="#다음에-만들어보고-싶은-것들" aria-label="Permalink to “다음에 만들어보고 싶은 것들”">​</a></h2><h3 id="next-js-블로그-플랫폼" tabindex="-1">Next.js 블로그 플랫폼 <a class="header-anchor" href="#next-js-블로그-플랫폼" aria-label="Permalink to “Next.js 블로그 플랫폼”">​</a></h3><p><strong>왜 만들고 싶나?</strong><br> VitePress도 좋지만, 더 동적인 기능들(댓글, 좋아요, 검색 등)이 있는 블로그를 만들어보고 싶어요. Next.js의 SSR과 API Routes를 활용해서 풀스택 경험을 쌓고 싶습니다.</p><p><strong>예상 기술 스택</strong>: Next.js, TypeScript, Prisma, PostgreSQL</p><hr><h3 id="개발자를-위한-유틸리티-도구" tabindex="-1">개발자를 위한 유틸리티 도구 <a class="header-anchor" href="#개발자를-위한-유틸리티-도구" aria-label="Permalink to “개발자를 위한 유틸리티 도구”">​</a></h3><p><strong>왜 만들고 싶나?</strong><br> 개발하면서 자주 사용하는 작업들(JSON 포맷팅, 색상 코드 변환, 정규표현식 테스트 등)을 한 곳에 모아둔 도구가 있으면 편할 것 같아요.</p><p><strong>예상 기술 스택</strong>: React, TypeScript, PWA</p><hr><h3 id="팀-프로젝트-경험" tabindex="-1">팀 프로젝트 경험 <a class="header-anchor" href="#팀-프로젝트-경험" aria-label="Permalink to “팀 프로젝트 경험”">​</a></h3><p><strong>왜 중요한가?</strong><br> 혼자 개발하는 것과 팀으로 개발하는 것은 완전히 다른 경험이라고 들었어요.<br> Git 협업, 코드 리뷰, 업무 분담 등을 실제로 경험해보고 싶습니다.</p><hr><h2 id="개발하며-배운-것들" tabindex="-1">개발하며 배운 것들 <a class="header-anchor" href="#개발하며-배운-것들" aria-label="Permalink to “개발하며 배운 것들”">​</a></h2><h3 id="기술적-성장" tabindex="-1">기술적 성장 <a class="header-anchor" href="#기술적-성장" aria-label="Permalink to “기술적 성장”">​</a></h3><ul><li><strong>React Hooks</strong> 패턴과 상태 관리의 복잡성</li><li><strong>TypeScript</strong>로 런타임 에러를 줄이는 경험</li><li><strong>Git</strong>을 활용한 버전 관리와 배포 자동화</li><li><strong>반응형 디자인</strong>의 중요성과 구현 방법</li></ul><h3 id="프로젝트-관리" tabindex="-1">프로젝트 관리 <a class="header-anchor" href="#프로젝트-관리" aria-label="Permalink to “프로젝트 관리”">​</a></h3><ul><li><strong>작은 단위로 나누어 개발</strong>하는 것의 중요성</li><li><strong>사용자 관점</strong>에서 기능을 바라보는 시각</li><li><strong>완벽함보다는 완성</strong>을 우선시하는 마인드</li><li><strong>문서화</strong>와 <strong>코드 주석</strong>의 필요성</li></ul><hr><p><strong>새로운 프로젝트는 계속 추가됩니다!</strong></p>',38)])])}const b=a(i,[["render",s]]);export{c as __pageData,b as default};
